using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;
namespace Ara {
 public sealed class NotionDiaryAuto:IDisposable {
  readonly object gate=new object();readonly string file;readonly NotionHub hub;readonly Timer timer;Dictionary<string,object> root;bool busy,disposed,requested;string target="";
  static long Now(){return (long)(DateTime.UtcNow-new DateTime(1970,1,1)).TotalMilliseconds;}
  static JavaScriptSerializer Codec(){return new JavaScriptSerializer{MaxJsonLength=16*1024*1024,RecursionLimit=80};}
  public NotionDiaryAuto(string dataFile,NotionHub value){file=Path.Combine(Path.GetDirectoryName(dataFile),"notion-diary-queue.json");hub=value;root=File.Exists(file)?Codec().Deserialize<Dictionary<string,object>>(File.ReadAllText(file)):JsonMap.Obj("items",JsonMap.Obj(),"enabled",true);timer=new Timer(_=>Process(),null,Timeout.Infinite,Timeout.Infinite);}
  Dictionary<string,object> Items(){var items=JsonMap.Child(root,"items");root["items"]=items;return items;}
  void Save(){JsonMap.Atomic(file,Codec().Serialize(root));}
  bool Enabled(){return !root.ContainsKey("enabled")||JsonMap.Str(root,"enabled")=="True";}
  static object Canonical(object obj){var d=obj as Dictionary<string,object>;if(d!=null)return d.OrderBy(x=>x.Key,StringComparer.Ordinal).ToDictionary(x=>x.Key,x=>Canonical(x.Value));var a=obj as System.Collections.IEnumerable;if(a!=null&&!(obj is string))return a.Cast<object>().Select(Canonical).ToArray();return obj;}
  public static string Hash(Dictionary<string,object> payload){return JsonMap.Hash(JsonMap.Write(Canonical(payload)));}
  bool Pending(Dictionary<string,object> item){return JsonMap.Str(item,"skipped")!="True"&&(JsonMap.Str(item,"hash")!=JsonMap.Str(item,"syncedHash")||target!=JsonMap.Str(item,"syncedTarget"));}
  public void Enqueue(State state){var payloads=new List<Dictionary<string,object>>();foreach(var day in state.Days)try{payloads.Add(NotionDiary.Payload(state,day.Date));}catch(Exception e){Diagnostics.Error("diary-export",e);}EnqueuePayloads(payloads);}
  public void EnqueuePayloads(IEnumerable<Dictionary<string,object>> payloads){bool changed=false;lock(gate){foreach(var payload in payloads){if(JsonMap.Str(payload,"op")!="diary")throw new InvalidDataException("일기 저장 요청만 대기시킬 수 있습니다.");string date=NotionDaily.Date(payload),hash=Hash(payload);bool skipped=!NotionDiary.Active(payload);var item=JsonMap.Child(Items(),date);if(JsonMap.Str(item,"hash")==hash&&JsonMap.Str(item,"skipped")==skipped.ToString())continue;item["payload"]=payload;item["hash"]=hash;item["skipped"]=skipped;item["retryAt"]=0L;item["attempts"]=0;item["error"]="";Items()[date]=item;changed=true;}if(changed)Save();}if(changed)Poke();}
  public void Poke(){lock(gate){if(!disposed){requested=true;timer.Change(5000,60000);}}}
  public void RetryNow(){lock(gate){foreach(var item in Items().Values.Select(JsonMap.Map))item["retryAt"]=0L;Save();}Poke();}
  public void SetEnabled(bool enabled){lock(gate){root["enabled"]=enabled;Save();if(!enabled)timer.Change(Timeout.Infinite,Timeout.Infinite);}if(enabled)Poke();}
  public object Status(){lock(gate){var pending=Items().Where(x=>Pending(JsonMap.Map(x.Value))).ToArray();var problem=pending.FirstOrDefault(x=>JsonMap.Str(JsonMap.Map(x.Value),"error").Length>0);string error=problem.Key==null?JsonMap.Str(root,"error"):problem.Key+": "+JsonMap.Str(JsonMap.Map(problem.Value),"error");return JsonMap.Obj("enabled",Enabled(),"busy",busy,"pending",pending.Length,"lastSyncedAt",JsonMap.Str(root,"lastSyncedAt"),"lastDate",JsonMap.Str(root,"lastDate"),"error",error);}}

  public void Process(){lock(gate){if(disposed||busy||!Enabled())return;busy=true;requested=false;}try{var status=JsonMap.Map(hub.Request(JsonMap.Obj("op","status")));var destination=JsonMap.Child(status,"target");if(JsonMap.Str(status,"connected")!="True"||destination.Count==0)return;lock(gate)target=JsonMap.Str(destination,"id");KeyValuePair<string,object>[] list;lock(gate)list=Items().OrderBy(x=>x.Key).Select(x=>new KeyValuePair<string,object>(x.Key,Codec().DeserializeObject(Codec().Serialize(x.Value)))).ToArray();foreach(var pair in list){var item=JsonMap.Map(pair.Value);lock(gate){if(!Enabled()||disposed)break;if(!Pending(item))continue;}long retry;long.TryParse(JsonMap.Str(item,"retryAt"),out retry);if(retry>Now())continue;string hash=JsonMap.Str(item,"hash"),sentTarget=target;try{var result=JsonMap.Map(hub.Request(JsonMap.Child(item,"payload")));if(JsonMap.Str(result,"saved")!="True"&&JsonMap.Str(result,"skipped")!="True")throw new InvalidOperationException("노션 저장 완료를 확인하지 못했습니다.");lock(gate){var current=JsonMap.Child(Items(),pair.Key);if(JsonMap.Str(current,"hash")==hash){current["syncedHash"]=hash;current["syncedTarget"]=sentTarget;current["lastSyncedAt"]=Now();current["error"]="";current["retryAt"]=0L;current["attempts"]=0;root["lastSyncedAt"]=Now();root["lastDate"]=pair.Key;root["error"]="";Save();}}}catch(Exception e){lock(gate){var current=JsonMap.Child(Items(),pair.Key);if(JsonMap.Str(current,"hash")==hash){int attempts;int.TryParse(JsonMap.Str(current,"attempts"),out attempts);current["attempts"]=++attempts;current["retryAt"]=Now()+Math.Min(900000,15000L*(1L<<Math.Min(attempts,6)));current["error"]=root["error"]=e.Message.Length>600?e.Message.Substring(0,600):e.Message;Save();}}if(!e.Message.Contains("생성 결과")&&!e.Message.Contains("같은 기상일")&&!e.Message.Contains("구역"))break;}}}catch(Exception e){lock(gate)root["error"]=e.Message;}finally{lock(gate){busy=false;if(Items().Values.All(x=>!Pending(JsonMap.Map(x)))&&!disposed&&!requested)timer.Change(Timeout.Infinite,Timeout.Infinite);}}}
  public void Dispose(){lock(gate){disposed=true;timer.Dispose();}}
 }
}
